   String cookie=login.response().headerValue("Set-Cookie").split(";",2)[0];Class<?> config=Class.forName("kr.workbench.BountySession$Config",true,loader),session=Class.forName("kr.workbench.BountySession",true,loader);var ctor=config.getDeclaredConstructor(boolean.class,String.class,String.class,String.class,String.class,String.class,String.class,String.class);ctor.setAccessible(true);Object cfg=ctor.newInstance(true,base+"/api/auth/me","","authorization","Bearer ","$.csrf","x-csrf-token","$.user.ID");
